def camel_to_snake(name: str) -> str:
    if not name:
        return name

    result = []
    for i, char in enumerate(name):
        if char.isupper():
            if i > 0:
                prev_char = name[i - 1]
                if prev_char.islower() or prev_char.isdigit():
                    result.append('_')
                elif prev_char.isupper() and i + 1 < len(name) and name[i + 1].islower():
                    result.append('_')
            result.append(char.lower())
        else:
            result.append(char)

    return ''.join(result)
