def median(values) -> float:
    if not values:
        raise ValueError("values is empty")

    sorted_values = sorted(values)
    n = len(sorted_values)

    if n % 2 == 1:
        return float(sorted_values[n // 2])
    else:
        mid1 = sorted_values[n // 2 - 1]
        mid2 = sorted_values[n // 2]
        return float((mid1 + mid2) / 2)
