def truncate_words(text: str, limit: int) -> str:
    if limit < 1:
        raise ValueError("limit must be at least 1")

    if len(text) <= limit:
        return text

    words = text.split()

    if not words:
        return "…"

    result = ""
    for word in words:
        if result:
            candidate = result + " " + word
        else:
            candidate = word

        if len(candidate) + 1 <= limit:
            result = candidate
        else:
            break

    if not result:
        first_word = words[0]
        result = first_word[:limit - 1]

    return result + "…"
