def truncate_words(text: str, limit: int) -> str:
    if limit < 1:
        raise ValueError("limit must be at least 1")

    if len(text) <= limit:
        return text

    # Find all word boundaries (positions right after a word)
    boundaries = []
    in_word = False
    for i, char in enumerate(text):
        if not char.isspace():
            in_word = True
        elif in_word:
            boundaries.append(i)
            in_word = False

    if in_word:
        boundaries.append(len(text))

    # Try each boundary from longest to shortest
    for boundary in reversed(boundaries):
        prefix = text[:boundary].rstrip()
        if len(prefix) + 1 <= limit:
            return prefix + "…"

    # No word boundary fits
    return text[:limit - 1] + "…"
